class Solution {
    public int[] searchRange(int[] nums, int target) {
        int start = -1, end = -1;

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == target) {
                if (start == -1) start = i;   // 第一次
                end = i;                      // 一直更新到最后一个
            }
        }
        return new int[]{start, end};
    }
}

class Solution {
    public int[] searchRange(int[] nums, int target) {
        int l = findLeft(nums, target);
        if (l == -1) return new int[]{-1, -1};   // 左边界都没有，右边界也不用找
        int r = findRight(nums, target);
        return new int[]{l, r};
    }

    private int findLeft(int[] nums, int target) {
        int left = 0, right = nums.length - 1, ans = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                ans = mid;
                right = mid - 1;      // 命中不返回，继续往左收缩
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }

    private int findRight(int[] nums, int target) {
        int left = 0, right = nums.length - 1, ans = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                ans = mid;
                left = mid + 1;       // 命中不返回，继续往右收缩
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int[] searchRange(int[] nums, int target) {
        int lb = bound(nums, target, true);
        // 短路顺序必须这样写：先判越界，再取值
        if (lb == nums.length || nums[lb] != target) {
            return new int[]{-1, -1};
        }
        int ub = bound(nums, target, false);
        return new int[]{lb, ub - 1};
    }

    // lower=true 求下界（第一个 >= target），false 求上界（第一个 > target）
    private int bound(int[] nums, int target, boolean lower) {
        int left = 0, right = nums.length;   // 左闭右开
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target || (!lower && nums[mid] == target)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
